  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'hi', timestamp: SENT_AT}],
};

const throwingProvider = (value: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw value;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

